    if (organizationId === "0") {
      organizationId = this.getVarSystem("deptIds").split(",")[0];
    }

    console.log("Table putaway item", data.table_putaway_item);
    // Validate quantities and update line statuses
    const { updatedItems, errors } = validateAndUpdateLineStatuses(
      data.table_putaway_item,
    );

    console.log("updatedItems", updatedItems);
    if (errors.length > 0) {
      this.hideLoading();
      this.$message.error(errors.join("; "));
      return;
    }

    // Determine the new transfer order status
    const newTransferOrderStatus = determineTransferOrderStatus(updatedItems);
    console.log(
      `Determined new transfer order status: ${newTransferOrderStatus}`,
    );

    // Block process if status would be "In Progress"
    if (
      newTransferOrderStatus === "In Progress" ||
      newTransferOrderStatus === "Created"
    ) {
      console.log("Blocking process: Transfer Order status is In Progress");

      // Get incomplete items for better user feedback
      const incompleteItems = updatedItems
        .map((item, index) => ({
          ...item,
          itemName: item.item_code || `Item #${index + 1}`,
          qtyToPutaway: parseFloat(item.qty_to_putaway) || 0,
          putawayQty: parseFloat(item.putaway_qty) || 0,
        }))
        .filter((item) => {
          const putawayQty = item.putawayQty;
          const qtyToPutaway = item.qtyToPutaway;
          return putawayQty < qtyToPutaway && putawayQty > 0;
        });

      const unPutawayItem = updatedItems
        .map((item, index) => ({
          ...item,
          itemName: item.item_code || `Item #${index + 1}`,
          qtyToPutaway: parseFloat(item.qty_to_putaway) || 0,
          putawayQty: parseFloat(item.putaway_qty) || 0,
        }))
        .filter((item) => item.putawayQty === 0);

      // Create concise message
      let detailMessage = "Incomplete putaway detected. ";

      if (incompleteItems.length > 0) {
        detailMessage += `${incompleteItems.length} item(s) partially putaway. `;
      }

      if (unPutawayItem.length > 0) {
        detailMessage += `${unPutawayItem.length} item(s) not started. `;
      }

      detailMessage +=
        "Please complete all putaway or save as In Progress to continue later.";

      this.hideLoading();

      this.$alert(detailMessage, "Putaway Items Incomplete", {
        confirmButtonText: "OK",
        type: "warning",
        dangerouslyUseHTMLString: false,
      });

      console.log("Process blocked due to incomplete putaway");
      throw new Error("Process blocked: Incomplete putaway items detected");
    }

    // Update the form data with the new line statuses (only if we proceed)
    for (let index = 0; index < updatedItems.length; index++) {
      this.setData({
        [`table_putaway_item.${index}.line_status`]:
          updatedItems[index].line_status,
      });
    }

    const latestPutawayItems = updatedItems
      .filter((item) => item.parent_or_child === "Parent")
      .map((item) => ({ ...item })); // Shallow copy each object

    for (const putaway of latestPutawayItems) {
      putaway.is_split = "No";
      putaway.target_location = "";
      putaway.remark = "";
      putaway.putaway_qty = 0;
    }

    toData.to_status = newTransferOrderStatus;
    toData.organization_id = organizationId;
    toData.table_putaway_item = latestPutawayItems;

    await createPutawayRecords(toData, updatedItems);

    // Clean up undefined/null values
    Object.keys(toData).forEach((key) => {
      if (toData[key] === undefined || toData[key] === null) {
        delete toData[key];
      }
    });

    const isAutoCompleteGR = await db
      .collection("putaway_setup")
      .where({ plant_id: toData.plant_id, organization_id: organizationId })
      .get()
      .then((res) => {
        if (res.data.length > 0) {
          return res.data[0].auto_completed_gr;
        }
      });

    let toId;

    // Perform action based on page status
    if (page_status === "Add") {
      await addEntry(organizationId, toData);
      await processInventoryMovementandBalanceTable(toData, updatedItems);
      await updateGoodsReceiving(data.gr_no, isAutoCompleteGR, organizationId);
    } else if (page_status === "Edit") {
      toId = data.id;
      await updateEntry(organizationId, toData, toId, originalToStatus);
      await processInventoryMovementandBalanceTable(toData, updatedItems);
      await updateGoodsReceiving(data.gr_no, isAutoCompleteGR, organizationId);
    }

    // Success message with status information
    const statusMessage =
      newTransferOrderStatus !== originalToStatus
        ? ` (Status updated to: ${newTransferOrderStatus})`
        : "";

    this.$message.success(
      `${
        page_status === "Add" ? "Added" : "Updated"
      } successfully${statusMessage}`,
    );

    this.hideLoading();
    closeDialog();
  } catch (error) {
    this.hideLoading();

    let errorMessage = "";
    if (error && typeof error === "object") {
      errorMessage =
        findFieldMessage(error || String(error)) || "An error occurred";
    } else {
      errorMessage = error;
    }

    this.$message.error(errorMessage);
    console.error(errorMessage);
  }
})();

const closeDialog = () => {
  if (this.parentGenerateForm) {
    this.parentGenerateForm.$refs.SuPageDialogRef.hide();
    this.parentGenerateForm.refresh();
  }
};

// Saving as In Progress is the same operation as saving as Completed: the workflow
// works out to_status from the line statuses it computes, so a partial putaway lands
// on In Progress and a full one on Completed. The difference between the two buttons
// is only that Completed additionally refuses a partial putaway of a handling unit.
//
// This used to be a 68 KB client-side reimplementation of that workflow which walked
// table_putaway_item top level only. With an item bundle that meant the bundle row --
// which holds no stock -- was booked as if it were a real line, none of the items
// under it moved at all, and their putaway_qty was left behind for the next Complete
// to post a second time.
(async () => {
  try {
    this.showLoading("Saving Putaway as In Progress...");

    const data = this.getValues();
    const arrayData = Array.isArray(data) ? data : [data];

    let workflowResult;

    await this.runWorkflow(
      "2031190421336195074",
      {
        arrayData: arrayData,
        saveAs: "In Progress",
        pageStatus: data.page_status,
        confirmed_by: this.getVarGlobal("nickname"),
      },
      async (res) => {
        console.log("Putaway saved successfully:", res);
        workflowResult = res;
      },
      (err) => {
        console.error("Failed to save Putaway:", err);
        this.hideLoading();
        workflowResult = err;
      },
    );

    if (!workflowResult || !workflowResult.data) {
      this.hideLoading();
      this.$message.error("No response from workflow");
      return;
    }

    if (
      workflowResult.data.code === "400" ||
      workflowResult.data.code === 400 ||
      workflowResult.data.success === false
    ) {
      this.hideLoading();
      this.$message.error(
        workflowResult.data.msg ||
          workflowResult.data.message ||
          "Failed to save Putaway",
      );
      return;
    }

    if (
      workflowResult.data.code === "200" ||
      workflowResult.data.code === 200 ||
      workflowResult.data.success === true
    ) {
      this.hideLoading();
      this.$message.success(
        workflowResult.data.message ||
          workflowResult.data.msg ||
          "Putaway saved successfully",
      );
      closeDialog();
    } else {
      this.hideLoading();
      this.$message.error("Unknown workflow status");
    }
  } catch (error) {
    this.hideLoading();
    console.error("Error:", error);
    this.$message.error(error.message || "Failed to save Putaway");
  }
})();

(async () => {
  try {
    const grNo = await this.getValue("gr_no");
    const plantId = await this.getValue("plant_id");

    const fetchSerialNumber = async () => {
      try {
        const table_putaway_item = this.getValue("table_putaway_item");

        if (
          !Array.isArray(table_putaway_item) ||
          table_putaway_item.length === 0
        ) {
          console.log("No putaway items found for serial number fetching");
          return;
        }

        for (const [index, putaway] of table_putaway_item.entries()) {
          if (putaway.is_serialized_item === 1) {
            const resSerialNumber = await db
              .collection("serial_number")
              .where({ transaction_no: grNo, plant_id: plantId })
              .get();
            if (resSerialNumber.data && resSerialNumber.data.length > 0) {
              putaway.serial_numbers = resSerialNumber.data
                .map((serial) => serial.system_serial_number)
                .join(", ");
              await this.setData({
                [`table_putaway_item.${index}.serial_numbers`]:
                  putaway.serial_numbers,
              });
            }
          }
        }
      } catch (error) {
        console.error("Error fetching serial numbers:", error);
      }
    };

    const viewSerialNumber = async () => {
      const table_putaway_item = this.getValue("table_putaway_item");
      const table_putaway_records = this.getValue("table_putaway_records");
      if (table_putaway_item.length > 0) {
        for (const putaway of table_putaway_item) {
          if (putaway.is_serialized_item === 1) {
            await this.display("table_putaway_item.select_serial_number");
          }
        }
      }
      if (table_putaway_records.length > 0) {
        for (const putaway of table_putaway_records) {
          if (
            putaway.serial_numbers !== "" &&
            putaway.serial_numbers !== null
          ) {
            await this.display("table_putaway_records.serial_numbers");
          }
        }
      }
    };

    const setSerialNumber = async () => {
      try {
        const table_putaway_item = this.getValue("table_putaway_item");

        // Check if table_putaway_item exists and is an array
        if (
          !Array.isArray(table_putaway_item) ||
          table_putaway_item.length === 0
        ) {
          console.log("No putaway items found or invalid data structure");
          return;
        }

        for (const [index, putaway] of table_putaway_item.entries()) {
          try {
            // Check if item is serialized
            if (putaway.is_serialized_item === 1) {
              console.log(
                `Processing serialized item at index ${index}:`,
                putaway.item_code || putaway.id,
              );

              // Check if serial_numbers exists and is not empty
              if (
                !putaway.serial_numbers ||
                putaway.serial_numbers === null ||
                putaway.serial_numbers === undefined ||
                typeof putaway.serial_numbers !== "string" ||
                putaway.serial_numbers.trim() === ""
              ) {
                console.warn(
                  `No valid serial numbers found for item at index ${index}`,
                );
                continue;
              }

              // Split and clean serial numbers
              const serialNumbers = putaway.serial_numbers
                .split(",")
                .map((sn) => sn.trim())
                .filter((sn) => sn !== "");

              if (serialNumbers.length === 0) {
                console.warn(
                  `No valid serial numbers after processing for item at index ${index}`,
                );
                continue;
              }

              console.log(
                `Setting ${serialNumbers.length} serial numbers for item at index ${index}:`,
                serialNumbers,
              );

              // Set option data for select dropdown
              await this.setOptionData(
                [`table_putaway_item.${index}.select_serial_number`],
                serialNumbers,
              );

              // Set the actual data
              await this.setData({
                [`table_putaway_item.${index}.select_serial_number`]:
                  serialNumbers,
              });

              // Disable putaway_qty field for serialized items
              await this.disabled(
                [`table_putaway_item.${index}.putaway_qty`],
                true,
              );

              console.log(
                `Successfully set serial numbers for item at index ${index}`,
              );
            }
          } catch (itemError) {
            console.error(
              `Error processing item at index ${index}:`,
              itemError,
            );
            // Continue with next item instead of breaking the entire function
            continue;
          }
        }
      } catch (error) {
        console.error("Error in setSerialNumber function:", error);
        // Don't throw error to prevent breaking the entire onMounted flow
      }
    };

    const grData = await db
      .collection("goods_receiving")
      .where({ id: grNo })
      .get()
      .then((response) => {
        if (response.data && response.data.length > 0) {
          return response.data[0];
        }
        return null;
      });

    if (!grData) {
      console.error(`Goods Receiving with ID ${grNo} not found`);
      return;
    }

    if (
      !grData.table_gr ||
      !Array.isArray(grData.table_gr) ||
      grData.table_gr.length === 0
    ) {
      console.error("No GR items found in the goods receiving record");
      return;
    }

    let tablePutawayItem = [];

    let organizationId = this.getVarGlobal("deptParentId");
    if (organizationId === "0") {
      organizationId = this.getVarSystem("deptIds").split(",")[0];
    }

    // Fetch putaway setup for loading bay logic
    const resPutawaySetup = await db
      .collection("putaway_setup")
      .where({ plant_id: plantId, is_deleted: 0, movement_type: "Good Receiving" })
      .get();
    const putawaySetup = resPutawaySetup?.data?.[0] || {};

    let sourceBin = "";
    if (putawaySetup.is_loading_bay === 1 && putawaySetup.default_loading_bay && putawaySetup.default_loading_bay !== "") {
      sourceBin = putawaySetup.default_loading_bay;
    }

    for (const [index, item] of grData.table_gr.entries()) {
      try {
        // Skip items without item_id
        if (!item.item_id) {
          console.log(`Skipping item at index ${index} - no item_id`);
          continue;
        }

        // Skip split parent rows
        const isSplitParent = (item.is_split || "No") === "Yes" && (item.parent_or_child || "Parent") === "Parent";
        if (isSplitParent) {
          console.log(`Skipping split parent item at index ${index}`);
          continue;
        }

        const resItem = await db
          .collection("Item")
          .where({ id: item.item_id })
          .get();

        if (!resItem || !resItem.data || resItem.data.length === 0) {
          console.warn(`Item ${item.item_id} not found in Item collection`);
          continue;
        }

        const itemData = resItem.data[0];
        if (
          (itemData.receiving_inspection === 0 &&
            item.inv_category === "Quality Inspection") ||
          item.inv_category !== "Quality Inspection"
        ) {
          let batchNo = null;

          if (item.item_batch_no && item.item_batch_no !== "-") {
            try {
              const resBatch = await db
                .collection("batch")
                .where({
                  batch_number: item.item_batch_no,
                  organization_id: organizationId,
                })
                .get();
              batchNo = resBatch?.data?.[0] || null;
            } catch (batchError) {
              console.warn(
                `Error fetching batch ${item.item_batch_no}:`,
                batchError,
              );
            }
          }

          // Process HU data
          let huData = "";
          const tempHuDataStr = item.temp_hu_data || "[]";
          let tempHuData = [];
          let huItem = null;

          try {
            tempHuData = JSON.parse(tempHuDataStr);
          } catch (e) {
            tempHuData = [];
          }

          const hasHuData = Array.isArray(tempHuData) && tempHuData.length > 0 ? 1 : 0;

          if (hasHuData === 1) {
            huItem = tempHuData[0];

            const huInfo = {
              table_hu_items: [
                {
                  material_id: item.item_id,
                  material_name: item.item_name || "",
                  material_desc: item.item_desc || "",
                  location_id: item.location_id || "",
                  batch_id: batchNo?.id || null,
                  material_uom: item.base_item_uom || item.item_uom || "",
                  quantity: item.base_received_qty || huItem?.store_in_quantity || 0,
                  balance_id: "",
                },
              ],
              hasHuData: 1,
              handling_unit_id: huItem?.handling_unit_id || "",
              handling_no: huItem?.handling_no || "",
              hu_material_id: huItem?.hu_material_id || "",
              hu_type: huItem?.hu_type || "",
              hu_uom: huItem?.hu_uom || "",
              remark: huItem?.remark || "",
            };

            huData = JSON.stringify(huInfo);
          }

          tablePutawayItem.push({
            line_index: index + 1,
            item_code: item.item_id,
            item_name: item.item_name || "",
            item_desc: item.item_desc || "",
            batch_no: batchNo?.id || "",
            source_inv_category: item.inv_category || "",
            target_inv_category: "Unrestricted",
            received_qty: item.received_qty || 0,
            item_uom: item.item_uom || "",
            source_bin: sourceBin || item.location_id || "",
            qty_to_putaway: item.received_qty || 0,
            pending_process_qty: item.received_qty || 0,
            putaway_qty: 0,
            storage_location: sourceBin ? item.storage_location_id || "" : "",
            target_location: sourceBin ? item.location_id || "" : "",
            remark: "",
            qi_no: null,
            line_status: "Open",
            po_no: item.line_po_id || "",
            is_split: "No",
            parent_or_child: "Parent",
            parent_index: index,
            unit_price: item.unit_price || 0,
            total_price: (item.unit_price || 0) * (item.received_qty || 0),
            is_serialized_item: item.is_serialized_item || 0,
            gr_line_id: item.id || "",
            hu_data: huData,
          });
        }
      } catch (itemError) {
        console.error(`Error processing GR item at index ${index}:`, itemError);
        continue;
      }
    }

    await this.setData({
      receiving_no: grData.gr_no || "",
      table_putaway_item: tablePutawayItem,
      supplier_id: grData.supplier_name || "",
      created_by: this.getVarGlobal("nickname") || "",
      created_at: new Date().toISOString().slice(0, 19).replace("T", " "),
      organization_id: organizationId,
    });

    console.log(
      `Successfully created putaway with ${tablePutawayItem.length} items from GR ${grData.gr_no}`,
    );

    // Disable split button for items with HU data
    for (const [index, item] of tablePutawayItem.entries()) {
      if (item.hu_data && item.hu_data !== "") {
        this.disabled([`table_putaway_item.${index}.button_split`], true);
      }
    }

    // Wait for setData to complete (if needed by the platform)
    // Then process serial numbers in proper sequence
    try {
      await fetchSerialNumber();
      await viewSerialNumber();
      await setSerialNumber();

      // Trigger putaway strategy after all serial number processing is complete
      this.triggerEvent("func_getPutawayStrategy");
    } catch (serialError) {
      console.error("Error processing serial numbers:", serialError);
      // Still trigger strategy even if serial processing fails
      this.triggerEvent("func_getPutawayStrategy");
    }
  } catch (error) {
    console.error("Error fetching Goods Receiving:", error);
  }
})();

